<section class="section"><div class="ready-grid smart-ready-grid">${READY.map(x=>{const key=x[0],complete=!!state.checklist[key],auto=key==='flight';return `<article class="card check-card smart-check-card ${complete?'is-complete':''}"><div class="ready-check-wrap">${auto?`<span class="auto-check ${complete?'checked':''}">${complete?'✓':''}</span>`:`<input type="checkbox" data-action="ready" data-key="${key}" ${complete?'checked':''}>`}</div><div class="ready-card-copy"><div class="meta">${complete?'Complete':'To do'}</div><h3>${x[1]}</h3>${auto&&!complete?'<p>Automatically completes when both flights are saved.</p>':''}${readyAction(key)}</div></article>`}).join('')}</div></section>
